import React, { useState, useEffect } from 'react';
import { Tree } from 'primereact/tree';
import { NodeService } from './service/NodeService';

export default function Filter() {
    const [nodes, setNodes] = useState([]);
    
    useEffect(() => {
        NodeService.getTreeNodes().then((data) => setNodes(data));
    }, []);

    return (
        <div className="card fvc fhc">
            <Tree value={nodes} filter filterMode="lenient" filterPlaceholder="Lenient Filter" className="w300" />
            <Tree value={nodes} filter filterMode="strict" filterPlaceholder="Strict Filter" className="w300" />
        </div>
    )

}